# a battery of Excel functions on edge arguments (negative, fractional, zero, dates), driven by typed inputs
import openpyxl,sys
wb=openpyxl.Workbook();I=wb.active;I.title='Inputs'
ins=[('Negative fraction',-1.25),('Fraction',2.9),('Months fraction',1.9),('Start date',45322),('Rate',0.05),('Periods',10),('Amount',-1000),('Small',0.004),('Half',2.5),('Neg half',-2.5),('Count',3),('Zero',0),('Big',1234.5678),('Date 2',45500),('Pct',0.075),('Leap year end',50040),('Lag',2.2)]
for i,(l,v) in enumerate(ins,1):I.cell(i,1,l);I.cell(i,2,v)
C=wb.create_sheet('Calc');T=wb.create_sheet('Table')
for r in range(1,13):T.cell(r,1,r);T.cell(r,2,r*10);T.cell(r,3,45000+30*r);T.cell(r,4,'k%d'%r);T.cell(r,5,(r%4)-1.5)
n={l:f'Inputs!$B${i}' for i,(l,v) in enumerate(ins,1)}
