('ROUND half',f'=ROUND({H},0)'),('ROUND neg half',f'=ROUND({NH},0)'),('ROUND -2',f'=ROUND({BG},-2)'),('ROUNDUP neg',f'=ROUNDUP({NF},0)'),('ROUNDDOWN neg',f'=ROUNDDOWN({NF},0)'),('CEILING',f'=CEILING({F},1)'),('FLOOR',f'=FLOOR({F},1)'),('MROUND',f'=MROUND({BG},5)'),
('MOD neg',f'=MOD({NF},2)'),('MOD neg div',f'=MOD({F},-2)'),('QUOTIENT',f'=QUOTIENT({NF}*10,4)'),('EDATE frac',f'=EDATE({SD},{MF})'),('EDATE neg frac',f'=EDATE({SD},-{MF})'),('EOMONTH frac',f'=EOMONTH({SD},{MF})'),('EOMONTH neg',f'=EOMONTH({SD},-{MF})'),
('DATE frac month',f'=DATE(2024,{MF},1)'),('DATE month 13',f'=DATE(2024,12+{CN},1)'),('DATE day 0',f'=DATE(2024,3,{Z})'),('YEAR',f'=YEAR({SD})'),('MONTH',f'=MONTH({SD}+{F})'),('DAY',f'=DAY({D2})'),('YEARFRAC0',f'=YEARFRAC({SD},{D2})'),('YEARFRAC1',f'=YEARFRAC({SD},{D2},1)'),
('YEARFRAC3',f'=YEARFRAC({SD},{D2},3)'),('DAYS360',f'=DAYS360({SD},{D2})'),('DATEDIF m',f'=DATEDIF({SD},{D2},"m")'),('DATEDIF y',f'=DATEDIF({SD},{D2},"y")'),('DATEDIF d',f'=DATEDIF({SD},{D2},"d")'),('EOMONTH 0',f'=EOMONTH({D2},0)'),('WEEKDAY',f'=WEEKDAY({D2})'),
('NETWORKDAYS',f'=NETWORKDAYS({SD},{D2})'),('WORKDAY',f'=WORKDAY({SD},{CN}*{F})'),('PMT',f'=PMT({R}/12,{P}*12,{A})'),('PMT type1',f'=PMT({R},{P},{A},0,1)'),('FV frac',f'=FV({R},{P}+0.5,{A})'),('PV',f'=PV({R},{P},{A})'),('NPER',f'=NPER({R},{A}/10,-{A})'),
('RATE',f'=RATE({P},{A}/10,-{A}*0.8)'),('IPMT',f'=IPMT({R},1,{P},{A})'),('PPMT',f'=PPMT({R},2,{P},{A})'),('CUMIPMT',f'=CUMIPMT({R}/12,{P}*12,-{A},1,12,0)'),('NPV',f'=NPV({R},Table!B1:B12)'),('IRR',f'=IRR(Table!E1:E12)'),('XNPV',f'=XNPV({R},Table!E1:E12,Table!C1:C12)'),
('XIRR',f'=XIRR(Table!E1:E12,Table!C1:C12)'),('VLOOKUP approx',f'=VLOOKUP({F},Table!A1:B12,2)'),('VLOOKUP col frac',f'=VLOOKUP({CN},Table!A1:B12,{F})'),('VLOOKUP exact',f'=VLOOKUP({CN},Table!A1:B12,2,FALSE)'),('HLOOKUP',f'=HLOOKUP(2,Table!A1:B12,{CN})'),
('INDEX frac',f'=INDEX(Table!B1:B12,{F})'),('INDEX 2d frac',f'=INDEX(Table!A1:B12,{F},{F}-0.5)'),('MATCH approx',f'=MATCH({H},Table!A1:A12)'),('MATCH exact',f'=MATCH({CN},Table!A1:A12,0)'),('MATCH desc',f'=MATCH({CN}*10,Table!B1:B12,1)'),('LOOKUP',f'=LOOKUP({H},Table!A1:A12,Table!B1:B12)'),
('OFFSET frac',f'=SUM(OFFSET(Table!B1,{F},0,{F},1))'),('SUMIF',f'=SUMIF(Table!A1:A12,">"&{H},Table!B1:B12)'),('SUMIFS',f'=SUMIFS(Table!B1:B12,Table!A1:A12,">="&{CN},Table!E1:E12,"<0")'),('COUNTIF',f'=COUNTIF(Table!E1:E12,"<"&{Z})'),('AVERAGEIF',f'=AVERAGEIF(Table!A1:A12,">"&{F},Table!B1:B12)'),
