('ODD',f'=ODD({NF})'),('EVEN',f'=EVEN({F})'),('FACT frac',f'=FACT({F})'),('COMBIN',f'=COMBIN(5,{F})'),('NORM.DIST',f'=_xlfn.NORM.DIST({F},2,1,TRUE)'),('MAXIFS',f'=_xlfn.MAXIFS(Table!B1:B12,Table!E1:E12,"<0")'),('MINIFS',f'=_xlfn.MINIFS(Table!B1:B12,Table!E1:E12,">0")'),
('COUNTA',f'=COUNTA(Table!D1:D12)'),('COUNT',f'=COUNT(Table!A1:D12)'),('ISNUMBER',f'=IF(ISNUMBER(Table!D1),1,0)'),('ISBLANK',f'=IF(ISBLANK(Table!F1),1,0)'),('N text',f'=SUM(Table!D1:D12)'),('AVERAGE text',f'=AVERAGE(Table!C1:D12)'),
